#include <iostream>

int main() {
    int n = 0;
    std::cin >> n;

    int previous = 0;
    int climbs = 0;
    for (int i = 0; i < n; i++) {
        int x = 0;
        std::cin >> x;
        if (x > previous) {
            climbs = climbs + 1;
        }
        previous = x;
    }

    std::cout << "往上爬 " << climbs << " 次喵" << std::endl;
    return 0;
}
